INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0013-000000000009', '00000001-0000-0000-0000-000000000013', '00000000-0000-0000-0001-000000000001', 9, 'dialogos-cortos-repaso', '{"es": "Diálogos Cortos: Repaso", "en": "Short Dialogues: Review"}'::jsonb, '{"es": "Completa diálogos cortos eligiendo la respuesta que tiene sentido en el contexto — no solo la que es gramaticalmente correcta.", "en": "Complete short dialogues by choosing the response that makes sense in context — not just the grammatically correct one."}'::jsonb, 'mixed', 25, 15, '{"intro": "Hasta ahora practicaste oraciones sueltas. Aquí vas a completar una conversación real — las opciones incorrectas suelen ser gramaticalmente válidas, pero no tienen sentido en ese contexto. Lee todo el diálogo antes de responder.", "sections": [{"type": "note", "variant": "tip", "text": "Presta atención a la pregunta anterior: casi siempre te dice qué tipo de respuesta se espera (una razón, un lugar, una hora, un sí/no...)."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0013-0009-0001-000000000001', '00000002-0000-0000-0013-000000000009', 1, 'dialogue_fill', '{"lines": [{"speaker": "A", "text": "Hi! What''s your name?"}, {"speaker": "B", "text": "___"}, {"speaker": "A", "text": "Nice to meet you!"}]}'::jsonb, '{"text": "My name is Ana."}'::jsonb, '["I am fine, thanks.", "It''s Monday.", "I like pizza."]'::jsonb, '{"es": "La pregunta ''What''s your name?'' pide un nombre, no un estado de ánimo ni un día."}'::jsonb),
('00000003-0013-0009-0002-000000000001', '00000002-0000-0000-0013-000000000009', 2, 'dialogue_fill', '{"lines": [{"speaker": "A", "text": "Where do you live?"}, {"speaker": "B", "text": "___"}, {"speaker": "A", "text": "Oh, that''s a nice city!"}]}'::jsonb, '{"text": "I live in Bogotá."}'::jsonb, '["I am 25 years old.", "I have two brothers.", "I like coffee."]'::jsonb, '{"es": "''Where'' pregunta por un lugar — la respuesta debe mencionar una ciudad o lugar."}'::jsonb),
('00000003-0013-0009-0003-000000000001', '00000002-0000-0000-0013-000000000009', 3, 'dialogue_fill', '{"lines": [{"speaker": "A", "text": "Do you like coffee?"}, {"speaker": "B", "text": "___"}, {"speaker": "A", "text": "Me too! Let''s get some."}]}'::jsonb, '{"text": "Yes, I love it."}'::jsonb, '["No, I am a teacher.", "It''s raining today.", "She is my sister."]'::jsonb, '{"es": "''Do you like...?'' pide una respuesta de sí/no sobre un gusto."}'::jsonb),
('00000003-0013-0009-0004-000000000001', '00000002-0000-0000-0013-000000000009', 4, 'dialogue_fill', '{"lines": [{"speaker": "A", "text": "Can you help me, please?"}, {"speaker": "B", "text": "___"}, {"speaker": "A", "text": "Thank you so much!"}]}'::jsonb, '{"text": "Of course! What do you need?"}'::jsonb, '["I don''t like vegetables.", "She has blue eyes.", "It''s ten o''clock."]'::jsonb, '{"es": "Es una petición de ayuda — la respuesta lógica acepta o rechaza ayudar, no cambia de tema."}'::jsonb),
('00000003-0013-0009-0005-000000000001', '00000002-0000-0000-0013-000000000009', 5, 'dialogue_fill', '{"lines": [{"speaker": "A", "text": "Excuse me, is there a pharmacy near here?"}, {"speaker": "B", "text": "___"}, {"speaker": "A", "text": "Great, thank you!"}]}'::jsonb, '{"text": "Yes, there is one on Main Street."}'::jsonb, '["I am from Peru.", "He can play guitar.", "My name is Carlos."]'::jsonb, '{"es": "''Is there...?'' pregunta por la existencia de algo — la respuesta debe confirmar o negar y decir dónde."}'::jsonb),
('00000003-0013-0009-0006-000000000001', '00000002-0000-0000-0013-000000000009', 6, 'dialogue_fill', '{"lines": [{"speaker": "A", "text": "How old are you?"}, {"speaker": "B", "text": "___"}, {"speaker": "A", "text": "Wow, you''re young!"}]}'::jsonb, '{"text": "I am twenty years old."}'::jsonb, '["I don''t have a car.", "It''s cold today.", "We are friends."]'::jsonb, '{"es": "''How old...?'' pregunta por la edad, así que la respuesta necesita un número de años."}'::jsonb),
('00000003-0013-0009-0007-000000000001', '00000002-0000-0000-0013-000000000009', 7, 'dialogue_fill', '{"lines": [{"speaker": "A", "text": "What time is it?"}, {"speaker": "B", "text": "___"}, {"speaker": "A", "text": "Thanks, I need to go now."}]}'::jsonb, '{"text": "It''s three o''clock."}'::jsonb, '["I am hungry.", "She likes music.", "There are five books."]'::jsonb, '{"es": "''What time is it?'' pide la hora — la respuesta debe mencionar un momento del día."}'::jsonb);
